// features/auth.feature: "Signing out clears the session cookie" (AUTH-06)
// The openapi.json description for /api/auth/logout requires this test to be
// declared with test.skip() until the cookie rewrite ships, so it does not run.
import { expect, expectStatus, test } from "../fixtures";

test.describe("sign out", () => {
  test.skip("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");

    // Act
    const response = await member.post("/api/auth/logout");

    // Assert
    expect(response.status()).toBe(204);
    await expectStatus(response, 204);
    const cookie = response
      .headersArray()
      .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
    expect(cookie).toBeDefined();
    const value = cookie?.value.toLowerCase() ?? "";
    // A cleared cookie has an empty value or an expiry in the past / Max-Age=0.
    expect(value.startsWith("session=;") || value.includes("max-age=0") || value.includes("expires=thu, 01 jan 1970")).toBe(true);
  });
});
